// Le a classificacao que a Groq devolveu e so deixa passar o que da para confiar.
// Falha FECHADA: valor estranho para o fluxo AQUI, nunca chega na tela de aprovacao.

// Dominios aceitos. Valor fora daqui e erro, nao aviso: o banco tem CHECK nessas colunas
// e a tela de pendentes ordena por urgencia — texto livre quebraria as duas coisas.
const ASSUNTOS_ACEITOS = ['warranty', 'exchange', 'delivery', 'billing', 'product_info', 'complaint', 'other'];
const URGENCIAS_ACEITAS = ['low', 'medium', 'high'];

// O modelo as vezes embrulha o JSON em prosa ou em crases (```json ... ```).
// Varre o texto de tras para frente e devolve o ULTIMO bloco {...} com chaves balanceadas.
// De tras para frente porque, quando o modelo "pensa alto", o JSON bom e o ultimo.
function ultimoBlocoBalanceado(texto) {
  let fim = texto.lastIndexOf('}');
  while (fim !== -1) {
    let nivel = 0;
    for (let i = fim; i >= 0; i--) {
      if (texto[i] === '}') nivel++;
      else if (texto[i] === '{') {
        nivel--;
        if (nivel === 0) return texto.slice(i, fim + 1);
      }
    }
    fim = texto.lastIndexOf('}', fim - 1);
  }
  return null;
}

const entrada = $input.first().json;

// 1. O no HTTP foi configurado com neverError+fullResponse, entao erro da Groq NAO explode
//    o no: chega aqui como statusCode. Traduzimos para uma mensagem que diz o que fazer.
const status = entrada.statusCode;
if (status !== 200) {
  const motivo = status === 429
    ? 'limite de uso da Groq atingido (429) — esperar a janela reabrir'
    : `a Groq respondeu HTTP ${status}`;
  throw new Error(`Classify message falhou: ${motivo}. Nada segue adiante.`);
}

// 2. O texto do modelo nunca vem na superficie da resposta: mora em choices[0].message.
//    Se essa estrutura mudar, preferimos parar a adivinhar onde o texto foi parar.
const mensagem = entrada.body && entrada.body.choices && entrada.body.choices[0] && entrada.body.choices[0].message;
if (!mensagem) {
  throw new Error('Classify message: resposta da Groq sem choices[0].message — formato inesperado.');
}

// 3. Armadilha conhecida: modelo com raciocinio as vezes devolve content VAZIO
//    e deixa o texto em 'reasoning'. Sem este fallback o fluxo quebraria calado.
let texto = String(mensagem.content || '').trim();
let veioDoReasoning = false;
if (!texto) {
  texto = String(mensagem.reasoning || '').trim();
  veioDoReasoning = texto.length > 0;
}
if (!texto) {
  throw new Error('Classify message: a Groq devolveu content e reasoning vazios — nada para classificar.');
}

// 4. Extrair o JSON de dentro do texto, seja ele limpo ou embrulhado em prosa/crases.
const bruto = ultimoBlocoBalanceado(texto);
if (!bruto) {
  throw new Error(`Classify message: nenhum bloco JSON no texto do modelo. Recebido: ${texto.slice(0, 200)}`);
}

let dados;
try {
  dados = JSON.parse(bruto);
} catch (e) {
  throw new Error(`Classify message: o bloco encontrado nao e JSON valido. Recebido: ${bruto.slice(0, 200)}`);
}

// 5. Validar campo a campo. Modelo fraco inventa valor fora do dominio quando o schema
//    e forcado — caso conhecido. Aqui o valor invalido vira parada.
if (!ASSUNTOS_ACEITOS.includes(dados.subject)) {
  throw new Error(`Classify message: assunto "${dados.subject}" fora do dominio aceito.`);
}
if (!URGENCIAS_ACEITAS.includes(dados.urgency)) {
  throw new Error(`Classify message: urgencia "${dados.urgency}" fora do dominio aceito.`);
}
if (typeof dados.needs_human !== 'boolean') {
  throw new Error(`Classify message: needs_human precisa ser true/false, veio "${dados.needs_human}".`);
}
const resumo = typeof dados.summary === 'string' ? dados.summary.trim() : '';
if (!resumo) {
  throw new Error('Classify message: summary vazio — a tela de pendentes ficaria sem descricao.');
}

// 6. Saida enxuta e previsivel para os proximos nos. Os tokens viajam junto porque o teto
//    da conta gratuita e por DIA (200.000) — quem grava o pendente registra o consumo.
const uso = (entrada.body && entrada.body.usage) || {};
return [{
  json: {
    subject: dados.subject,
    urgency: dados.urgency,
    needs_human: dados.needs_human,
    summary: resumo,
    tokens_usados: uso.total_tokens || 0,
    veio_do_reasoning: veioDoReasoning,
  },
}];

