// Le o rascunho que o modelo escreveu, venha ele no campo que vier.
//
// Por que este no existe: o Basic LLM Chain nao promete ONDE o texto vem. Ja veio em
// 'text' e ja veio em 'output'. Apostar num campo so significa rascunho
// vazio chegando na tela de aprovacao — e o humano aprovando o nada.

// Um rascunho menor que isto nao e uma resposta ao cliente, e sobra de geracao.
const MINIMO_DE_CARACTERES = 20;

// Os lugares onde o texto ja apareceu, na ordem em que vale a pena procurar. A lista e
// explicita de proposito: campo novo entra aqui depois de ser MEDIDO, nunca por varredura
// magica que aceita qualquer coisa.
const CAMPOS_CONHECIDOS = ['text', 'output', 'response', 'content'];

function extrairTexto(saida) {
  // 1. O chain pode devolver a propria string, sem embrulho nenhum.
  if (typeof saida === 'string') return saida;
  if (!saida || typeof saida !== 'object') return null;

  // 2. Caminho normal: um dos campos conhecidos com a string dentro.
  for (const campo of CAMPOS_CONHECIDOS) {
    if (typeof saida[campo] === 'string' && saida[campo].trim()) return saida[campo];
  }

  // 3. Um nivel de aninhamento: { output: { text: "..." } } ja foi visto em versoes do chain.
  for (const campo of CAMPOS_CONHECIDOS) {
    const dentro = saida[campo];
    if (dentro && typeof dentro === 'object') {
      for (const interno of CAMPOS_CONHECIDOS) {
        if (typeof dentro[interno] === 'string' && dentro[interno].trim()) return dentro[interno];
      }
    }
  }

  return null;
}

const saida = $input.first().json;

// A classificacao nao vem por este fio (o chain so devolve o texto): buscamos no no que a produziu.
const classificacao = $('Parse classification').first().json;

// 1. Achar o texto onde quer que ele esteja. Se nao achar, o fluxo para aqui.
const bruto = extrairTexto(saida);
if (bruto === null) {
  const campos = saida && typeof saida === 'object' ? Object.keys(saida).join(', ') : typeof saida;
  throw new Error(`Draft reply: nao achei o texto do rascunho. Campos recebidos: ${campos}`);
}

// 2. Limpar as bordas. Modelo costuma devolver quebra de linha sobrando no inicio e no fim.
const texto = String(bruto).trim();

// 3. Falha FECHADA: rascunho vazio ou curto demais nunca chega na tela de aprovacao,
//    porque o humano aprovaria uma resposta em branco sem perceber.
if (!texto) {
  throw new Error('Draft reply: o modelo devolveu um rascunho vazio.');
}
if (texto.length < MINIMO_DE_CARACTERES) {
  throw new Error(`Draft reply: rascunho curto demais (${texto.length} caracteres): "${texto}"`);
}

// 4. O item de aprovacao carrega o rascunho E a classificacao, porque a tela de pendentes
//    mostra os dois lado a lado e o no seguinte grava tudo numa linha so.
return [{
  json: {
    subject: classificacao.subject || null,
    urgency: classificacao.urgency || null,
    needs_human: typeof classificacao.needs_human === 'boolean' ? classificacao.needs_human : null,
    summary: classificacao.summary || null,
    draft: texto,
    draft_chars: texto.length,
  },
}];
